import json,sys,re
sys.stdout.reconfigure(encoding='utf-8',errors='replace')
for f in ['b0f7ff9e-60c3-4c37-8b96-e48463d19359.jsonl','2bbb9c37-e964-47b7-a131-4c9d750e3fcb.jsonl']:
    rows=[json.loads(l) for l in open(f,encoding='utf-8') if l.strip()]
    def text(m):
        c=m.get('message',{}).get('content')
        if isinstance(c,str): return c
        out=[]
        if isinstance(c,list):
            for b in c:
                if b.get('type')=='text': out.append(b['text'])
        return '\n'.join(out)
    for i,r in enumerate(rows):
        if r.get('type') not in ('assistant','user'): continue
        t=text(r)
        if not t: continue
        for m in re.finditer(r'[^\n.]{0,200}(default\.yaml|config file|the config)[^\n.]{0,250}', t, re.I):
            s=m.group(0)
            if re.search(r'change|switch|update|revisit|later|todo|should|need|edit|adopt|bump|set ', s, re.I):
                print(f[:8], i, r.get('type'), '|', s.strip()[:400])
