"""One status line for the T-410 run. Emits progress, stalls and failures."""
import json, pathlib, time, sys
from datetime import datetime, timezone

TRACE = pathlib.Path("outputs/runs/t410_cap100/trace.jsonl")
LOG = pathlib.Path("outputs/t410_cap100.log")

if not TRACE.exists():
    print("[tick] no trace yet"); sys.exit(0)

rows = []
for line in TRACE.read_text(encoding="utf-8", errors="replace").splitlines():
    try:
        rows.append(json.loads(line))
    except Exception:
        pass
if not rows:
    print("[tick] trace empty"); sys.exit(0)

t0 = datetime.fromisoformat(rows[0]["ts"].replace("Z", "+00:00"))
now = datetime.now(timezone.utc)
mins = (now - t0).total_seconds() / 60
stale = (time.time() - TRACE.stat().st_mtime) / 60

searches = [r for r in rows if r["event"] == "search"]
errs = [r for r in searches if (r["payload"] or {}).get("error")]
papers = next((r["payload"]["new_papers"] for r in reversed(rows)
               if r["event"] == "retrieval_summary"), None)
chunks = next((r["payload"]["new_chunks"] for r in reversed(rows)
               if r["event"] == "retrieval_summary"), None)
ranked = next((r["payload"]["ranked"] for r in reversed(rows)
               if r["event"] == "rank_summary"), None)
extracted = next((r["payload"]["papers"] for r in reversed(rows)
                  if r["event"] == "extract_summary"), None)
decisions = [r["payload"].get("decision") for r in rows if r["event"] == "critic_decision"]
last = rows[-1]
stage = f"{last['agent']}/{last['event']}"

bits = [f"[{mins:5.1f}m] {stage:28s}"]
bits.append(f"searches={len(searches)}" + (f" ({len(errs)} err)" if errs else ""))
if papers is not None:
    bits.append(f"papers={papers} chunks={chunks}")
if ranked is not None:
    bits.append(f"ranked={ranked}")
if extracted is not None:
    bits.append(f"extracted={extracted}")
if decisions:
    bits.append(f"critic={decisions}")
if stale > 12:
    bits.append(f"** NO TRACE WRITE FOR {stale:.0f} MIN - possible stall **")
print("  ".join(bits))

if LOG.exists():
    txt = LOG.read_text(encoding="utf-8", errors="replace")
    for marker in ("Traceback", "TokenBudgetExceeded", "RateLimitExceeded",
                   "OpenAlexBudgetExhausted", "MemoryError", "KeyboardInterrupt"):
        if marker in txt:
            tail = [ln for ln in txt.splitlines() if marker in ln][-1]
            print(f"  !! {marker}: {tail[:200]}")
