"""Persistent Chroma vector store over Chunk objects."""

from __future__ import annotations

from pathlib import Path

import chromadb
from chromadb.config import Settings

from researchgpt.core.models import Chunk


class VectorStore:
    def __init__(
        self, path: str = "data/vectorstore", collection: str = "chunks"
    ) -> None:
        self._path = Path(path)
        self._path.mkdir(parents=True, exist_ok=True)
        self._client = chromadb.PersistentClient(
            path=str(self._path),
            settings=Settings(anonymized_telemetry=False),
        )
        self._collection = self._client.get_or_create_collection(
            name=collection,
            metadata={"hnsw:space": "cosine"},
        )

    def add(
        self, chunks: list[Chunk], embeddings: list[list[float]]
    ) -> None:
        if not chunks:
            return
        if len(chunks) != len(embeddings):
            raise ValueError("chunks and embeddings length mismatch")
        ids = [c.chunk_id for c in chunks]
        documents = [c.text for c in chunks]
        metadatas = [
            {
                "paper_id": c.paper_id,
                "section": c.section or "",
                "start_char": c.start_char,
                "end_char": c.end_char,
                "text": c.text,
            }
            for c in chunks
        ]
        # upsert so re-ingestion does not duplicate
        self._collection.upsert(
            ids=ids,
            embeddings=embeddings,
            documents=documents,
            metadatas=metadatas,
        )

    def query(
        self, embedding: list[float], k: int = 30
    ) -> list[tuple[str, float]]:
        n = min(k, max(self.count(), 1))
        if self.count() == 0:
            return []

