    if req.artefact is not None:
        events.append(("human_score", {
            "kind": "artefact", "target": req.artefact.artefact,
            "score": req.artefact.score, "note": req.artefact.note,
        }))
        artefact_row = {"artefact": req.artefact.artefact,
                        "score": req.artefact.score, "note": req.artefact.note}

