new6 = '''        <PanelScores v-if="onOptimizer" :run-id="runId" />'''
assert s.count(old6) == 1, "panel scores"
io.open(p, "w", encoding="utf-8", newline="\n").write(s.replace(old6, new6))
print("App ok")
