import io
p = "frontend/src/App.vue"
s = io.open(p, encoding="utf-8").read()

old = """import PanelScores from './components/PanelScores.vue'"""
new = """import PanelScores from './components/PanelScores.vue'
import DashboardView from './components/DashboardView.vue'"""
assert s.count(old) == 1, "import"
s = s.replace(old, new)

old2 = """// T-612 — the score sheet is reachable at /optimizer and nowhere else.
// A path check rather than vue-router: T-604 chose "one page, one run - a
// store is ceremony", and a router for a single conditional panel is the same
// kind of ceremony. Vite serves index.html for unknown paths (appType 'spa'),
// so /optimizer loads this app; navigation is a full page load, so this needs
// no reactivity.
const onOptimizer = ref(
  window.location.pathname.replace(/\\/+$/, '') === '/optimizer',
)"""
new2 = """// Three views, chosen by path. A path check rather than vue-router: T-604
// chose "one page, one run - a store is ceremony", and a router for three
// static routes is the same kind of ceremony. Vite serves index.html for
// unknown paths (appType 'spa'), so these all load this app; navigation
// between them is a full page load, so none of this needs to be reactive.
//
//   /dashboard  what the project is, for someone who has never seen it (T-613)
//   /optimizer  the run page plus the human scoring sheet (T-612)
//   /           the run page
const route = window.location.pathname.replace(/\\/+$/, '')
const onDashboard = ref(route === '/dashboard')
const onOptimizer = ref(route === '/optimizer')"""
assert s.count(old2) == 1, "route block"
s = s.replace(old2, new2)

old3 = """<template>
  <div class="app">
    <header class="top">"""
new3 = """<template>
  <DashboardView v-if="onDashboard" />

  <div v-else class="app">
    <header class="top">"""
assert s.count(old3) == 1, "template head"
s = s.replace(old3, new3)
